-- misma restricción de exclusión.
CREATE EXTENSION IF NOT EXISTS btree_gist;--> statement-breakpoint
CREATE TABLE "pago" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "pago_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"trabajo_id" integer NOT NULL,
	"monto" numeric(10, 2) NOT NULL,
	"metodo" text NOT NULL,
	"tipo" text NOT NULL,
	"fecha" date NOT NULL,
	"comprobante_archivo_id" integer,
	"anulado" boolean DEFAULT false NOT NULL,
	"motivo_anulacion" text,
	"anulado_at" timestamp with time zone,
	"anulado_por" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" integer NOT NULL,
	CONSTRAINT "pago_monto_positivo" CHECK ("pago"."monto" > 0),
	CONSTRAINT "pago_metodo_valido" CHECK ("pago"."metodo" in ('efectivo', 'qr', 'transferencia')),
	CONSTRAINT "pago_tipo_valido" CHECK ("pago"."tipo" in ('adelanto', 'saldo')),
	CONSTRAINT "pago_motivo_si_anulado" CHECK ("pago"."anulado" = ("pago"."motivo_anulacion" is not null))
);
--> statement-breakpoint
CREATE TABLE "trabajo" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "trabajo_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"sucursal_id" integer NOT NULL,
	"cliente_id" integer NOT NULL,
	"vehiculo_id" integer NOT NULL,
	"consulta_id" integer,
	"cotizacion_id" integer,
	"espacio_id" integer NOT NULL,
	"fecha_inicio" date NOT NULL,
	"fecha_fin" date NOT NULL,
	"hora_ingreso" text,
	"tecnico_id" integer,
	"descuento" numeric(10, 2) DEFAULT '0' NOT NULL,
	"estado" text DEFAULT 'agendado' NOT NULL,
	"nota" text,
	"motivo_cancelacion" text,
	"cancelado_at" timestamp with time zone,
	"cancelado_por" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" integer NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "trabajo_estado_valido" CHECK ("trabajo"."estado" in ('agendado', 'recibido', 'en_proceso', 'listo', 'entregado', 'cancelado')),
	CONSTRAINT "trabajo_fechas_validas" CHECK ("trabajo"."fecha_fin" >= "trabajo"."fecha_inicio"),
	CONSTRAINT "trabajo_descuento_valido" CHECK ("trabajo"."descuento" >= 0),
	CONSTRAINT "trabajo_motivo_si_cancelado" CHECK (("trabajo"."estado" = 'cancelado') = ("trabajo"."motivo_cancelacion" is not null))
);
