-- RN-06 y D-5: un espacio no tiene dos trabajos activos que se crucen en algún día (bordes incluidos). La base lo
-- rechaza aunque dos personas reserven a la vez o el código fallara. Los cancelados y entregados no ocupan.
ALTER TABLE "trabajo" ADD CONSTRAINT "trabajo_sin_cruces" EXCLUDE USING gist (
  "espacio_id" WITH =,
  daterange("fecha_inicio", "fecha_fin", '[]') WITH &&
) WHERE ("estado" NOT IN ('cancelado', 'entregado'));
